"""
erloese.py - Erlöse-Berechnung auf Basis von Faktur- und Refund-Daten.

Fachlicher Hintergrund
----------------------
Dieses Modul berechnet die Erlöse (Umsätze) einer Zeitung/ePaper-Ausgabe
für einen beliebigen Zeitraum. Die Grundlage ist das vorbereitete Modell
``dbm_stg.umsatz_sub_daily``: es fasst Fakturen und Refunds bereits
zusammen und liefert pro Abrechnungsperiode den Tagespreis (Daily
Revenue) - getrennt in Forderungen (positive Beträge) und Gutschriften
(negative Beträge), jeweils brutto und netto.

Kernidee der Berechnung
-----------------------
Eine Rechnung deckt meist einen längeren Zeitraum ab; das Modell
reicht bereits den Tagespreis an jede Zeile an (Rechnungsbetrag / Tage
im Zeitraum). Dieses Modul zerlegt die Periode in einzelne
Erscheinungstage, filtert auf den Auswertungszeitraum und aggregiert
optional auf Wochentags-Gruppen:

- Mo-Sa: alle Erscheinungstage von Montag bis Samstag
- Mo-Fr: alle Erscheinungstage von Montag bis Freitag
- Sa:    nur Samstags-Ausgaben

Diese Unterscheidung ist nötig, weil die IVW-Meldung nach
Erscheinungsrhythmus getrennt erfolgt.

Verwendung
----------
    from core_services.revenue.erloese import (
        erloese_final_aggregated,  # aggregierte Summen passend zur IVW-Meldung
        erloese_final_detail,      # kalendertaggenaue Liste für Analysen
    )
"""

import logging
from decimal import ROUND_HALF_UP, Decimal
from typing import Any

import pandas as pd

from ..db.client import connect_to_db

logger = logging.getLogger(__name__)

DAILY_UMSATZ_COLUMNS = [
    "SubscriptionId",
    "Orderid_for",
    "ActivationCode",
    "PeriodStart",
    "PeriodEnd",
    "faktur_pro_ET_gross",
    "faktur_pro_ET_net",
    "refund_pro_ET_gross",
    "refund_pro_ET_net",
]
IVW_SUBSCRIPTION_COLUMNS = ["pva", "SubscriptionId", "IVWCategory", "ART", "vkorg", "vkorg_n"]
PRODUCT_SUBSCRIPTION_COLUMNS = [
    "SubscriptionId",
    "Produkt",
    "Bereich",
    "Abogruppe",
]
VOUCHER_COLUMNS = ["VoucherCode", "IVWCategory"]
IVW_MAPPING_COLUMNS = ["IVWCategory_esuite", "IVWCategory", "Meldung"]
PVA_MAPPING_COLUMNS = ["eSuite", "SAP", "Bezeichnung", "Objekt"]
IVW_CALENDAR_OUTPUT_COLUMNS = [
    "PVA",
    "Bezeichnung",
    "Objekt",
    "Art",
    "Welt",
    "IVWKategorie",
    "Erscheinung",
    "Forderung_brutto",
    "Forderung_netto",
    "Gutschrift_brutto",
    "Gutschrift_netto",
]

# ============================================================
# HELPER-FUNKTIONEN (PRIVATE)
# ============================================================


def _round_monetary_amounts(amounts: pd.Series) -> pd.Series:
    """Rundet Geldbeträge kaufmännisch auf zwei Nachkommastellen.

    Bei genau fünf an der nächsten Stelle wird von null weg gerundet.
    Die Umwandlung über ``str`` verhindert, dass binäre Float-Artefakte
    die fachliche Rundung beeinflussen.
    """

    return amounts.map(
        lambda amount: (
            float(Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
            if pd.notna(amount)
            else amount
        )
    )


def _fetch_dataframe(cursor: Any, columns: list[str]) -> pd.DataFrame:
    """Erzeugt aus Cursor-Zeilen einen DataFrame mit stabilen Spalten.

    Args:
        cursor: MariaDB-Cursor nach einem ausgeführten SELECT.
        columns: Erwartete Spalten in der gewünschten Reihenfolge.

    Returns:
        DataFrame mit den erwarteten Spalten, auch wenn das SELECT keine Zeilen
        geliefert hat.
    """
    rows = cursor.fetchall()
    return pd.DataFrame(rows, columns=columns)


def _normalize_string_column(df: pd.DataFrame, column: str) -> None:
    """Normalisiert eine DataFrame-Spalte inplace auf Pandas-String-Dtype.

    Args:
        df: DataFrame mit der zu normalisierenden Spalte.
        column: Name der Spalte.
    """
    if column in df.columns:
        df[column] = df[column].astype("string")


def _load_daily_umsatz(cursor: Any, start_date: str, end_date: str) -> pd.DataFrame:
    """Lädt den bereits aufbereiteten Daily-Umsatz aus ``dbm_stg.umsatz_sub_daily``.

    Das Modell enthält Fakturen und Refunds zusammengeführt, Ausschlüsse
    bereits entfernt und pro Zeile den Tagespreis (brutto/netto) getrennt
    nach Forderungen und Gutschriften. Es werden alle Zeilen geladen,
    deren Abrechnungsperiode sich mit dem Auswertungszeitraum überschneidet.
    """
    logger.info(f"Lade Daily-Umsatz für Zeitraum {start_date} bis {end_date}...")
    cursor.execute(
        """
        SELECT
            SubscriptionId,
            orderid                          AS Orderid_for,
            activationcode                   AS ActivationCode,
            periodstartdate                  AS PeriodStart,
            periodenddate                    AS PeriodEnd,
            Daily_Revenue_Forderungen        AS faktur_pro_ET_gross,
            Daily_Revenue_net_Forderungen    AS faktur_pro_ET_net,
            Daily_Revenue_Gutschriften       AS refund_pro_ET_gross,
            Daily_Revenue_net_Gutschriften   AS refund_pro_ET_net
        FROM dbm_stg.umsatz_sub_daily
        WHERE periodstartdate <= %s
            AND periodenddate  >= %s
    """,
        (end_date, start_date),
    )
    data = _fetch_dataframe(cursor, DAILY_UMSATZ_COLUMNS)
    logger.info(f"Daily-Umsatz geladen: {len(data)} Zeilen")
    return data


def _load_ivw_subscriptions(cursor: Any) -> pd.DataFrame:
    """Laedt IVW-Stammdaten aus ``dbm_stg.subscription_stamm``.

    PVA, Art, Welt und IVW-Kategorie folgen damit derselben
    Berechnungsgrundlage wie das Monatsmodell. Die bestehenden
    IVW-Ausgabespalten bleiben unveraendert.
    """
    logger.info("Lade IVW-Subscriptions...")
    cursor.execute("""
        SELECT
            sub.pva,
            sub.SubscriptionId,
            sub.IVWCategory,
            CASE
                WHEN sub.Produkt REGEXP 'ePaper' THEN 'ePaper'
                ELSE sub.Produkt
            END AS ART,
            CASE WHEN sub.Vkorg IN ('AH', 'OT', 'WN', 'MZ') THEN 'MS'
                 WHEN sub.Vkorg IN ('HFK', 'ZPB', 'WBV') THEN 'OWL'
                 ELSE sub.Vkorg
            END AS vkorg,
            sub.vkorg AS vkorg_n
        FROM dbm_stg.subscription_stamm sub
    """)
    subscriptions = _fetch_dataframe(cursor, IVW_SUBSCRIPTION_COLUMNS)
    logger.info(f"IVW-Subscriptions geladen: {len(subscriptions)} Zeilen")
    return subscriptions


def _load_product_subscriptions(cursor: Any) -> pd.DataFrame:
    """Lädt Produkt- und Bereichs-Stammdaten aus ``dbm_stg.subscription_stamm``."""
    logger.info("Lade Produkt-Subscriptions...")
    cursor.execute("""
        SELECT
            sub.SubscriptionId,
            sub.Produkt,
            sub.Bereich,
            sub.Abogruppe
        FROM dbm_stg.subscription_stamm sub
    """)
    subscriptions = _fetch_dataframe(cursor, PRODUCT_SUBSCRIPTION_COLUMNS)
    logger.info(f"Produkt-Subscriptions geladen: {len(subscriptions)} Zeilen")
    return subscriptions


def _load_lookup_tables(cursor: Any) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Lädt alle benötigten Lookup-Tabellen (Stammdaten) aus der Datenbank.

    Es werden vier Nachschlagetabellen geladen, die später per JOIN an
    jede Rechnungszeile angehängt werden:

    - **Subscriptions**: IVW-Abo-Stammdaten mit PVA, IVW-Kategorie und
      Verkaufsorganisation (VkOrg).
    - **Vouchers**: Gutschein-Codes mit ihrer IVW-Kategorie. Ein
      eingelöster Gutschein kann die IVW-Kategorie des Abos überschreiben.
    - **IVW-Mapping**: Übersetzt interne eSuite-Kategorien in die offizielle
      IVW-Meldekategorie.
    - **PVA-Mapping**: Verknüpft die eSuite-PVA-Codes mit den SAP-Codes
      und den Anzeigenamen.
    """
    logger.info("Lade Lookup-Tabellen...")
    subscriptions = _load_ivw_subscriptions(cursor)

    cursor.execute("SELECT VoucherCode, IVWCategory FROM tb_vouchers_esuite")
    vouchers = _fetch_dataframe(cursor, VOUCHER_COLUMNS)
    logger.info(f"Vouchers geladen: {len(vouchers)} Zeilen")

    cursor.execute("SELECT IVWCategory_esuite, IVWCategory, Meldung FROM tb_ivw_mapping_ivwcategory")
    ivw_mapping = _fetch_dataframe(cursor, IVW_MAPPING_COLUMNS)
    logger.info(f"IVW Mapping geladen: {len(ivw_mapping)} Zeilen")

    cursor.execute("SELECT eSuite, SAP, Bezeichnung, Objekt FROM tb_mapping_pva")
    pva_mapping = _fetch_dataframe(cursor, PVA_MAPPING_COLUMNS)
    logger.info(f"PVA Mapping geladen: {len(pva_mapping)} Zeilen")

    return subscriptions, vouchers, ivw_mapping, pva_mapping


def _create_daily_data(data: pd.DataFrame, start_date: str, end_date: str) -> pd.DataFrame:
    """Zerlegt jede Perioden-Zeile in einzelne Erscheinungstage.

    Das Modell liefert bereits den Tagespreis pro Periode. Hier wird die
    Periode noch auf eine Zeile je Erscheinungstag aufgefächert ("explode")
    und auf den angefragten Auswertungszeitraum beschnitten - das ist
    nötig für die spätere Wochentags-Aggregation (Mo-Sa / Mo-Fr / Sa) und
    den Datumsfilter.
    """
    if data.empty:
        return pd.DataFrame()

    logger.info(f"Verarbeite {len(data)} Perioden und erstelle Tagesdaten...")

    data["PeriodStart"] = pd.to_datetime(data["PeriodStart"])
    data["PeriodEnd"] = pd.to_datetime(data["PeriodEnd"])
    data["Orderid_for"] = pd.to_numeric(data["Orderid_for"], errors="coerce").astype("Int64")
    for col in ["faktur_pro_ET_gross", "faktur_pro_ET_net", "refund_pro_ET_gross", "refund_pro_ET_net"]:
        data[col] = pd.to_numeric(data[col], errors="coerce").fillna(0)

    data["date_range"] = data.apply(
        lambda row: pd.date_range(start=row["PeriodStart"], end=row["PeriodEnd"], freq="D").tolist(), axis=1
    )
    daily_data = data.explode("date_range")
    daily_data.rename(columns={"date_range": "ET_Datum"}, inplace=True)

    daily_data = daily_data[
        (daily_data["ET_Datum"] >= pd.to_datetime(start_date)) & (daily_data["ET_Datum"] <= pd.to_datetime(end_date))
    ].copy()

    logger.info(f"Nach Datumsfilter: {len(daily_data)} Zeilen")

    daily_data = daily_data[
        [
            "SubscriptionId",
            "Orderid_for",
            "ActivationCode",
            "ET_Datum",
            "faktur_pro_ET_gross",
            "faktur_pro_ET_net",
            "refund_pro_ET_gross",
            "refund_pro_ET_net",
        ]
    ]

    logger.info(f"Tagesdaten erstellt: {len(daily_data)} Zeilen")
    return daily_data


def _create_daily_calendar_data(data: pd.DataFrame, start_date: str, end_date: str) -> pd.DataFrame:
    """Verteilt nur die Kalender-Schnittmenge einer Periode auf Tageszeilen.

    Diese Aufteilung entspricht der Berechnungsbasis von
    ``erloese_monthly.py``: Die ueberlappenden Kalendertage werden aus
    ``max(PeriodStart, start_date)`` bis ``min(PeriodEnd, end_date)``
    einschliesslich bestimmt. Die Tageserloese aus dem Staging-Modell werden
    dabei unveraendert je Kalendertag uebernommen.
    """
    if data.empty:
        return pd.DataFrame()

    logger.info("Verarbeite %s Perioden mit Kalendertags-Schnittmenge...", len(data))
    result = data.copy()
    result["PeriodStart"] = pd.to_datetime(result["PeriodStart"])
    result["PeriodEnd"] = pd.to_datetime(result["PeriodEnd"])
    result["Orderid_for"] = pd.to_numeric(result["Orderid_for"], errors="coerce").astype("Int64")
    for column in ["faktur_pro_ET_gross", "faktur_pro_ET_net", "refund_pro_ET_gross", "refund_pro_ET_net"]:
        result[column] = pd.to_numeric(result[column], errors="coerce").fillna(0)

    report_start = pd.to_datetime(start_date)
    report_end = pd.to_datetime(end_date)
    result["range_start"] = result["PeriodStart"].clip(lower=report_start)
    result["range_end"] = result["PeriodEnd"].clip(upper=report_end)
    result = result.loc[result["range_start"] <= result["range_end"]].copy()
    result["date_range"] = result.apply(
        lambda row: pd.date_range(start=row["range_start"], end=row["range_end"], freq="D").tolist(), axis=1
    )
    daily_data = result.explode("date_range").rename(columns={"date_range": "ET_Datum"})

    return daily_data[
        [
            "SubscriptionId",
            "Orderid_for",
            "ActivationCode",
            "ET_Datum",
            "faktur_pro_ET_gross",
            "faktur_pro_ET_net",
            "refund_pro_ET_gross",
            "refund_pro_ET_net",
        ]
    ]


def _add_month_year(daily_data: pd.DataFrame) -> pd.DataFrame:
    """Ergänzt Monat und Jahr aus dem Erscheinungstag."""
    result = daily_data.copy()
    result["MONAT"] = result["ET_Datum"].dt.month
    result["Jahr"] = result["ET_Datum"].dt.year
    return result


def _apply_joins(
    daily_data: pd.DataFrame,
    subscriptions: pd.DataFrame,
    vouchers: pd.DataFrame,
    ivw_mapping: pd.DataFrame,
    pva_mapping: pd.DataFrame,
) -> pd.DataFrame:
    """Reichert jede Tagesrechnung mit Stammdaten und IVW-Zuordnungen an.

    Abarbeitungsreihenfolge (jeder Schritt ist ein "Left-Join", d.h. alle
    Zeilen bleiben erhalten, passende Zusatzinfos werden angehängt):

    1. **Subscription-Daten**: holt PVA, Art (Print/ePaper), Welt (MS/OWL)
       und die Basis-IVW-Kategorie zum Abo.
    2. **Voucher-Überschreibung**: Wurde ein Gutschein eingelöst, ersetzt
       dessen IVW-Kategorie die Abo-Kategorie. Grund: Ein Abo kann z.B.
       als "Abo" geführt werden, ein Probegutschein macht daraus aber
       IVW-technisch ein "Probeabo".
    3. **IVW-Mapping**: übersetzt die interne Kategorie in die offizielle
       IVW-Meldekategorie ("Meldung").
    4. **PVA-Mapping**: SAP-Code, Bezeichnung, Objekt.

    Zwei Fallback-Spalten werden erzeugt:
      SAP_final   - SAP-Code falls vorhanden, sonst eSuite-PVA-Code.
      vkorg_final - Welt MS/OWL falls zuordenbar, sonst das rohe VkOrg-Kürzel.
    """
    logger.info("Führe JOINs durch...")

    daily_data["SubscriptionId"] = pd.to_numeric(daily_data["SubscriptionId"], errors="coerce").astype("Int64")
    subscriptions["SubscriptionId"] = pd.to_numeric(subscriptions["SubscriptionId"], errors="coerce").astype("Int64")

    result = daily_data.merge(subscriptions, on="SubscriptionId", how="left")
    _normalize_string_column(result, "ActivationCode")
    _normalize_string_column(result, "pva")
    _normalize_string_column(vouchers, "VoucherCode")
    _normalize_string_column(ivw_mapping, "IVWCategory_esuite")
    _normalize_string_column(pva_mapping, "eSuite")

    result = result.merge(
        vouchers.rename(columns={"IVWCategory": "IVWCategory_voucher"}),
        left_on="ActivationCode",
        right_on="VoucherCode",
        how="left",
    )
    result["IVWCategory_final"] = result["IVWCategory_voucher"].fillna(result["IVWCategory"])
    _normalize_string_column(result, "IVWCategory_final")

    result = result.merge(
        ivw_mapping, left_on="IVWCategory_final", right_on="IVWCategory_esuite", how="left", suffixes=("", "_mapped")
    )
    result = result.merge(pva_mapping, left_on="pva", right_on="eSuite", how="left")
    result["SAP_final"] = result["SAP"].fillna(result["pva"]).fillna("Unbekannt")
    result["Bezeichnung"] = result["Bezeichnung"].fillna("Unbekannt")
    result["Objekt"] = result["Objekt"].fillna("Unbekannt")
    result["ART"] = result["ART"].fillna("Unbekannt")
    result["vkorg_final"] = result["vkorg"].fillna(result["vkorg_n"]).fillna("Unbekannt")
    result["IVWCategory_mapped"] = result["IVWCategory_mapped"].fillna(result["IVWCategory_final"]).fillna("Unbekannt")

    return result


def _apply_product_joins(daily_data: pd.DataFrame, subscriptions: pd.DataFrame) -> pd.DataFrame:
    """Reichert jede Tagesrechnung mit Produkt und Bereich an."""
    logger.info("Führe Produkt-JOINs durch...")

    daily_data["SubscriptionId"] = pd.to_numeric(daily_data["SubscriptionId"], errors="coerce").astype("Int64")
    subscriptions["SubscriptionId"] = pd.to_numeric(subscriptions["SubscriptionId"], errors="coerce").astype("Int64")

    result = daily_data.merge(subscriptions, on="SubscriptionId", how="left")

    unmatched = result["Produkt"].isna().sum()
    if unmatched > 0:
        logger.warning(
            f"{unmatched} Zeilen ({unmatched / len(result):.1%}) ohne Treffer in "
            "dbm_stg.subscription_stamm werden als 'Unbekannt' gewertet."
        )
    result["Produkt"] = result["Produkt"].fillna("Unbekannt")
    result["Bereich"] = result["Bereich"].fillna("Unbekannt")
    result["Abogruppe"] = result["Abogruppe"].fillna("Unbekannt")

    return result


def _aggregate_final(result: pd.DataFrame) -> pd.DataFrame:
    """Summiert die Tages-Erlöse zur IVW-Meldekategorie auf.

    Ergebnis ist eine tabelle, die pro PVA / Art / Welt / IVW-Kategorie
    und pro **Erscheinungs-Rhythmus** eine Zeile enthält. Die Rhythmen sind:

      - "Mo-Sa": Summe aller Werktage + Samstag
      - "Mo-Fr": Summe nur Werktage (ohne Samstag)
      - "Sa":    Summe nur Samstags

    Derselbe Tag taucht also in mehreren Rhythmen auf (ein Dienstag liegt
    sowohl in "Mo-Sa" als auch "Mo-Fr"). Das ist fachlich so gewollt,
    weil IVW-Meldungen je nach Produkt einen dieser Rhythmen verlangen.

    Die vier Erlös-Spalten werden am Ende umbenannt:
      Forderung_brutto/netto  = aufaddierter Rechnungsbetrag
      Gutschrift_brutto/netto = aufaddierter Refund (als negative Zahl)
    """
    logger.info("Erstelle finale Aggregation im Long-Format...")

    # Wochentag in MySQL-Konvention berechnen:
    #   1 = Sonntag, 2 = Montag, ..., 7 = Samstag.
    # Pandas liefert 0=Mo..6=So, daher die Umrechnung.
    result["weekday_mysql"] = ((pd.to_datetime(result["ET_Datum"]).dt.dayofweek + 1) % 7) + 1

    group_cols = ["SAP_final", "Bezeichnung", "Objekt", "ART", "vkorg_final", "IVWCategory_mapped"]
    agg_cols = {
        "faktur_pro_ET_gross": "sum",
        "faktur_pro_ET_net": "sum",
        "refund_pro_ET_gross": "sum",
        "refund_pro_ET_net": "sum",
    }

    def _agg_erscheinung(df_filtered: pd.DataFrame, label: str) -> pd.DataFrame:
        """Aggregiert Erloese fuer einen einzelnen Erscheinungsrhythmus."""
        agg = df_filtered.groupby(group_cols).agg(agg_cols).reset_index()
        agg["Erscheinung"] = label
        return agg

    # Drei parallele Summen über unterschiedliche Wochentags-Filter:
    #   Mo-Sa = Wochentag 2..7 (Mo bis Sa)
    #   Mo-Fr = Wochentag 2..6 (Mo bis Fr, ohne Samstag)
    #   Sa    = Wochentag 7    (nur Samstag)
    agg_mo_sa = _agg_erscheinung(result[result["weekday_mysql"].between(2, 7)], "Mo-Sa")
    agg_mo_fr = _agg_erscheinung(result[result["weekday_mysql"].between(2, 6)], "Mo-Fr")
    agg_sa = _agg_erscheinung(result[result["weekday_mysql"] == 7], "Sa")

    final_agg = pd.concat([agg_mo_sa, agg_mo_fr, agg_sa], ignore_index=True)

    for col in ["faktur_pro_ET_gross", "faktur_pro_ET_net", "refund_pro_ET_gross", "refund_pro_ET_net"]:
        final_agg[col] = _round_monetary_amounts(final_agg[col])

    final_agg = final_agg.rename(
        columns={
            "SAP_final": "PVA",
            "ART": "Art",
            "vkorg_final": "Welt",
            "IVWCategory_mapped": "IVWKategorie",
            "faktur_pro_ET_gross": "Forderung_brutto",
            "faktur_pro_ET_net": "Forderung_netto",
            "refund_pro_ET_gross": "Gutschrift_brutto",
            "refund_pro_ET_net": "Gutschrift_netto",
        }
    )

    logger.info(f"Finale Aggregation erstellt: {len(final_agg)} Zeilen (Long-Format mit Erscheinung)")
    return final_agg


def _aggregate_product_final(result: pd.DataFrame) -> pd.DataFrame:
    """Summiert die Tages-Erlöse nach Produkt, Bereich, Monat und Jahr auf."""
    logger.info("Erstelle finale Produkt-Aggregation...")

    group_cols = ["Produkt", "Bereich", "Abogruppe", "MONAT", "Jahr"]
    agg_cols = {
        "faktur_pro_ET_gross": "sum",
        "faktur_pro_ET_net": "sum",
        "refund_pro_ET_gross": "sum",
        "refund_pro_ET_net": "sum",
    }

    final_agg = result.groupby(group_cols).agg(agg_cols).reset_index()

    for col in ["faktur_pro_ET_gross", "faktur_pro_ET_net", "refund_pro_ET_gross", "refund_pro_ET_net"]:
        final_agg[col] = _round_monetary_amounts(final_agg[col])

    final_agg = final_agg.rename(
        columns={
            "faktur_pro_ET_gross": "Forderung_brutto",
            "faktur_pro_ET_net": "Forderung_netto",
            "refund_pro_ET_gross": "Gutschrift_brutto",
            "refund_pro_ET_net": "Gutschrift_netto",
        }
    )

    logger.info(f"Finale Produkt-Aggregation erstellt: {len(final_agg)} Zeilen")
    return final_agg


def _aggregate_product_daily(result: pd.DataFrame) -> pd.DataFrame:
    """Summiert die Tages-Erlöse nach Produkt, Bereich und Erscheinungstag auf."""
    logger.info("Erstelle tägliche Produkt-Aggregation...")

    group_cols = ["Produkt", "Bereich", "Abogruppe", "ET_Datum", "MONAT", "Jahr"]
    agg_cols = {
        "faktur_pro_ET_gross": "sum",
        "faktur_pro_ET_net": "sum",
        "refund_pro_ET_gross": "sum",
        "refund_pro_ET_net": "sum",
    }

    final_agg = result.groupby(group_cols).agg(agg_cols).reset_index()

    for col in ["faktur_pro_ET_gross", "faktur_pro_ET_net", "refund_pro_ET_gross", "refund_pro_ET_net"]:
        final_agg[col] = _round_monetary_amounts(final_agg[col])

    final_agg = final_agg.rename(
        columns={
            "faktur_pro_ET_gross": "Forderung_brutto",
            "faktur_pro_ET_net": "Forderung_netto",
            "refund_pro_ET_gross": "Gutschrift_brutto",
            "refund_pro_ET_net": "Gutschrift_netto",
        }
    )

    logger.info(f"Tägliche Produkt-Aggregation erstellt: {len(final_agg)} Zeilen")
    return final_agg


def _aggregate_subscription_daily(result: pd.DataFrame) -> pd.DataFrame:
    """Aggregiert Erlöse je Subscription und Erscheinungstag.

    Eine Subscription kann an einem Tag mehrere Zeilen erhalten, wenn
    unterschiedliche Produkt-, Abo- oder IVW-Klassifikationen vorliegen.
    """
    logger.info("Erstelle tägliche Subscription-Aggregation...")

    group_cols = [
        "SubscriptionId",
        "ET_Datum",
        "Produkt",
        "Bereich",
        "Abogruppe",
        "SAP_final",
        "Bezeichnung",
        "Objekt",
        "ART",
        "vkorg_final",
        "IVWCategory_final",
        "IVWCategory_mapped",
    ]

    final_agg = result.groupby(
        group_cols,
        dropna=False,
        as_index=False,
    ).agg(
        Anzahl_Auftraege=("Orderid_for", "nunique"),
        Forderung_brutto=("faktur_pro_ET_gross", "sum"),
        Forderung_netto=("faktur_pro_ET_net", "sum"),
        Gutschrift_brutto=("refund_pro_ET_gross", "sum"),
        Gutschrift_netto=("refund_pro_ET_net", "sum"),
    )

    final_agg["MONAT"] = final_agg["ET_Datum"].dt.month
    final_agg["Jahr"] = final_agg["ET_Datum"].dt.year

    amount_columns = [
        "Forderung_brutto",
        "Forderung_netto",
        "Gutschrift_brutto",
        "Gutschrift_netto",
    ]
    for col in amount_columns:
        final_agg[col] = _round_monetary_amounts(final_agg[col])

    final_agg = final_agg.rename(
        columns={
            "SAP_final": "PVA",
            "ART": "Art",
            "vkorg_final": "Welt",
            "IVWCategory_final": "IVWCategory_esuite",
            "IVWCategory_mapped": "IVWCategory",
        }
    )

    final_agg = final_agg[
        [
            "SubscriptionId",
            "ET_Datum",
            "MONAT",
            "Jahr",
            "Produkt",
            "Bereich",
            "Abogruppe",
            "PVA",
            "Bezeichnung",
            "Objekt",
            "Art",
            "Welt",
            "IVWCategory_esuite",
            "IVWCategory",
            "Anzahl_Auftraege",
            "Forderung_brutto",
            "Forderung_netto",
            "Gutschrift_brutto",
            "Gutschrift_netto",
        ]
    ]

    final_agg = final_agg.sort_values(
        ["SubscriptionId", "ET_Datum", "Produkt", "IVWCategory"],
        ignore_index=True,
    )

    logger.info(
        "Tägliche Subscription-Aggregation erstellt: %s Zeilen für %s Subscriptions",
        len(final_agg),
        final_agg["SubscriptionId"].nunique(),
    )

    return final_agg


