def _aggregate_final_kalendertage(result: pd.DataFrame) -> pd.DataFrame:
    """Summiert Tageserloese ueber alle Kalendertage mit Kennwert ``Mo-Sa``.

    Der Kennwert dient zur Kompatibilitaet mit dem IVW-Outputformat. Anders als
    die bestehende Rhythmusaggregation werden Sonntage nicht herausgefiltert.
    """
    group_columns = ["SAP_final", "Bezeichnung", "Objekt", "ART", "vkorg_final", "IVWCategory_mapped"]
    amount_columns = {
        "faktur_pro_ET_gross": "sum",
        "faktur_pro_ET_net": "sum",
        "refund_pro_ET_gross": "sum",
        "refund_pro_ET_net": "sum",
    }
    final_agg = result.groupby(group_columns).agg(amount_columns).reset_index()
    final_agg["Erscheinung"] = "Mo-Sa"

    for column in amount_columns:
        final_agg[column] = _round_monetary_amounts(final_agg[column])

    return final_agg.rename(
        columns={
            "SAP_final": "PVA",
            "ART": "Art",
            "vkorg_final": "Welt",
            "IVWCategory_mapped": "IVWKategorie",
            "faktur_pro_ET_gross": "Forderung_brutto",
            "faktur_pro_ET_net": "Forderung_netto",
            "refund_pro_ET_gross": "Gutschrift_brutto",
            "refund_pro_ET_net": "Gutschrift_netto",
        }
    )


def erloese_final_aggregated(log_level: str, start_date: str, end_date: str) -> pd.DataFrame:
    """Berechnet die Erlös-Summen pro Produkt, Welt, IVW-Kategorie und Rhythmus.

    Dies ist die Haupt-Einstiegsfunktion für die IVW-Meldung. Sie führt
    nacheinander alle Berechnungsschritte aus:

    1. Daily-Umsatz (Fakturen + Refunds, bereits mit Tagespreis) aus
       ``dbm_stg.umsatz_sub_daily`` laden.
    2. Stammdaten (Abos, Gutscheine, IVW-, PVA-Mapping) laden.
    3. Perioden auf Erscheinungstage auffächern und auf den Zeitraum
       beschneiden.
    4. Jedem Tag die Stammdaten (PVA, Welt, IVW-Kategorie) zuordnen.
    5. Summen pro Produkt/Welt/IVW und Erscheinungs-Rhythmus (Mo-Sa,
       Mo-Fr, Sa) bilden.

    Das Ergebnis ist die Grundlage für die Spalten *Forderung_brutto/netto*
    und *Gutschrift_brutto/netto* im IVW-report.

    Args:
        log_level: Log-Level (z.B. 'INFO', 'DEBUG').
        start_date: Startdatum des Auswertungszeitraums ('YYYY-MM-DD').
        end_date: Enddatum des Auswertungszeitraums ('YYYY-MM-DD').

    Returns:
        DataFrame mit aggregierten Erlösen. Bei Fehlern oder leerem
        Ergebnis ein leerer DataFrame.
    """
    connection = None
    try:
        logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))

        connection = connect_to_db()
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return pd.DataFrame()

        cursor = connection.cursor(dictionary=True)

        umsatz_data = _load_daily_umsatz(cursor, start_date, end_date)
        if umsatz_data.empty:
            logger.warning("Keine Umsatzdaten gefunden!")
            return pd.DataFrame()

        subscriptions, vouchers, ivw_mapping, pva_mapping = _load_lookup_tables(cursor)

        daily_data = _create_daily_data(umsatz_data, start_date, end_date)
        if daily_data.empty:
            logger.info("Keine Daten im Zielzeitraum gefunden.")
            return pd.DataFrame()

        result = _apply_joins(daily_data, subscriptions, vouchers, ivw_mapping, pva_mapping)
        return _aggregate_final(result)

    except Exception as e:
        logger.error(f"Fehler bei der finalen Aggregation: {e}", exc_info=True)
        return pd.DataFrame()
    finally:
        if connection:
            connection.close()


def erloese_final_aggregated_kalendertage(log_level: str, start_date: str, end_date: str) -> pd.DataFrame:
    """Berechnet IVW-Erloese mit der Kalendertagslogik in SQL.

    Die Abfrage entspricht der Berechnungsbasis von ``erloese_monthly``:
    Sie schneidet jede Abrechnungsperiode mit dem angeforderten Zeitraum und
    multipliziert den Tagesbetrag mit der Anzahl ueberlappender Kalendertage.
    Stammdaten und Mappings werden direkt in SQL angereichert. Das Ergebnis
    behaelt das bestehende IVW-Ausgabeformat.
    """
    connection = None
    try:
        logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))
        connection = connect_to_db()
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return pd.DataFrame(columns=IVW_CALENDAR_OUTPUT_COLUMNS)

        cursor = connection.cursor(dictionary=True)
        cursor.execute(
            """
            WITH tageserloese AS (
                SELECT
                    stammdaten.PVA AS pva_quelle,
                    CASE
                        WHEN stammdaten.Produkt REGEXP 'ePaper' THEN 'ePaper'
                        ELSE stammdaten.Produkt
                    END AS art,
                    stammdaten.bereich as welt,
                    COALESCE(voucher.IVWCategory, stammdaten.IVWCategory, 'ABO') AS ivwcategory_esuite,
                    umsatz.Daily_Revenue_Forderungen AS faktur_pro_et_gross,
                    umsatz.Daily_Revenue_net_Forderungen AS faktur_pro_et_net,
                    umsatz.Daily_Revenue_Gutschriften AS refund_pro_et_gross,
                    umsatz.Daily_Revenue_net_Gutschriften AS refund_pro_et_net,
                    DATEDIFF(
                        LEAST(umsatz.periodenddate, DATE(%s)),
                        GREATEST(umsatz.periodstartdate, DATE(%s))
                    ) + 1 AS kalendertage_count
                FROM dbm_stg.umsatz_sub_daily AS umsatz
                LEFT JOIN dbm_stg.subscription_stamm AS stammdaten
                    ON stammdaten.SubscriptionId = umsatz.SubscriptionId
                LEFT JOIN dbm_lesermarkt.tb_vouchers_esuite AS voucher
                    ON voucher.VoucherCode = umsatz.activationcode
                WHERE umsatz.periodenddate >= DATE(%s)
                  AND umsatz.periodstartdate <= DATE(%s)
            ),
            angereichert AS (
                SELECT
                    COALESCE(pva_map.SAP, tageserloese.pva_quelle, 'Unbekannt') AS pva,
                    COALESCE(pva_map.Bezeichnung, 'Unbekannt') AS bezeichnung,
                    COALESCE(pva_map.Objekt, 'Unbekannt') AS objekt,
                    COALESCE(tageserloese.art, 'Unbekannt') AS art,
                    COALESCE(tageserloese.welt, 'Unbekannt') AS welt,
                    COALESCE(ivw_map.IVWCategory, tageserloese.ivwcategory_esuite, 'Unbekannt') AS ivwcategory,
                    tageserloese.faktur_pro_et_gross,
                    tageserloese.faktur_pro_et_net,
                    tageserloese.refund_pro_et_gross,
                    tageserloese.refund_pro_et_net,
                    tageserloese.kalendertage_count
                FROM tageserloese
                LEFT JOIN dbm_lesermarkt.tb_mapping_pva AS pva_map
                    ON pva_map.eSuite = tageserloese.pva_quelle
                LEFT JOIN dbm_lesermarkt.tb_ivw_mapping_ivwcategory AS ivw_map
                    ON ivw_map.IVWCategory_esuite = tageserloese.ivwcategory_esuite
            )
            SELECT
                pva AS PVA,
                bezeichnung AS Bezeichnung,
                objekt AS Objekt,
                art AS Art,
                welt AS Welt,
                ivwcategory AS IVWKategorie,
                'Mo-Sa' AS Erscheinung,
                CAST(SUM(faktur_pro_et_gross * kalendertage_count) AS DECIMAL(18, 4)) AS Forderung_brutto,
                CAST(SUM(faktur_pro_et_net * kalendertage_count) AS DECIMAL(18, 4)) AS Forderung_netto,
                CAST(SUM(refund_pro_et_gross * kalendertage_count) AS DECIMAL(18, 4)) AS Gutschrift_brutto,
                CAST(SUM(refund_pro_et_net * kalendertage_count) AS DECIMAL(18, 4)) AS Gutschrift_netto
            FROM angereichert
            GROUP BY pva, bezeichnung, objekt, art, welt, ivwcategory
            """,
            (end_date, start_date, start_date, end_date),
        )
        result = _fetch_dataframe(cursor, IVW_CALENDAR_OUTPUT_COLUMNS)
        if result.empty:
            logger.info("Keine Umsatzdaten im Zielzeitraum gefunden.")
            return result

        for column in [
            "Forderung_brutto",
            "Forderung_netto",
            "Gutschrift_brutto",
            "Gutschrift_netto",
        ]:
            result[column] = _round_monetary_amounts(result[column])
        logger.info("IVW-Kalendertagsaggregation erstellt: %s Zeilen", len(result))
        return result
    except Exception as error:
        logger.error("Fehler bei der Kalendertags-Aggregation: %s", error, exc_info=True)
        return pd.DataFrame(columns=IVW_CALENDAR_OUTPUT_COLUMNS)
    finally:
        if connection:
            connection.close()

def erloese_produkt_aggregated(log_level: str, start_date: str, end_date: str) -> pd.DataFrame:
    """Berechnet Erlös-Summen pro Produkt, Bereich, Monat und Jahr.

    Die Funktion nutzt dieselbe Umsatzbasis wie ``erloese_final_aggregated``,
    ordnet die Tagesdaten aber über ``dbm_stg.subscription_stamm`` Produkt und
    Bereich zu.

    Args:
        log_level: Log-Level (z.B. 'INFO', 'DEBUG').
        start_date: Startdatum des Auswertungszeitraums ('YYYY-MM-DD').
        end_date: Enddatum des Auswertungszeitraums ('YYYY-MM-DD').

    Returns:
        DataFrame mit aggregierten Erlösen. Bei Fehlern oder leerem Ergebnis
        ein leerer DataFrame.
    """
    connection = None
    try:
        logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))

        connection = connect_to_db()
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return pd.DataFrame()

        cursor = connection.cursor(dictionary=True)

        umsatz_data = _load_daily_umsatz(cursor, start_date, end_date)
        if umsatz_data.empty:
            logger.warning("Keine Umsatzdaten gefunden!")
            return pd.DataFrame()

        subscriptions = _load_product_subscriptions(cursor)

        daily_data = _create_daily_data(umsatz_data, start_date, end_date)
        if daily_data.empty:
            logger.info("Keine Daten im Zielzeitraum gefunden.")
            return pd.DataFrame()

        daily_data = _add_month_year(daily_data)
        result = _apply_product_joins(daily_data, subscriptions)
        return _aggregate_product_final(result)

    except Exception as e:
        logger.error(f"Fehler bei der finalen Produkt-Aggregation: {e}", exc_info=True)
        return pd.DataFrame()
    finally:
        if connection:
            connection.close()


