def erloese_subscription_daily(
    log_level: str,
    start_date: str,
    end_date: str,
) -> pd.DataFrame:
    """Berechnet tägliche Erlöse je Subscription.

    Verknüpft die Tageserlöse sowohl mit den Produkt-Stammdaten als auch
    mit den IVW-, Voucher- und PVA-Zuordnungen.

    Die Ausgabe enthält grundsätzlich eine Zeile je Subscription,
    Erscheinungstag und Klassifikationskombination.

    Args:
        log_level: Log-Level, zum Beispiel ``INFO`` oder ``DEBUG``.
        start_date: Startdatum im Format ``YYYY-MM-DD``.
        end_date: Enddatum im Format ``YYYY-MM-DD``.

    Returns:
        DataFrame mit täglichen Erlösen je Subscription inklusive Produkt,
        Bereich, Abogruppe und IVW-Kategorie.
    """
    connection = None

    try:
        logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))

        connection = connect_to_db()
        if not connection:
            logger.error("Keine Datenbankverbindung hergestellt!")
            return pd.DataFrame()

        cursor = connection.cursor(dictionary=True)

        # Umsatzdaten laden
        umsatz_data = _load_daily_umsatz(
            cursor,
            start_date,
            end_date,
        )
        if umsatz_data.empty:
            logger.warning("Keine Umsatzdaten gefunden!")
            return pd.DataFrame()

        # IVW-Stammdaten und Mappings laden
        (
            ivw_subscriptions,
            vouchers,
            ivw_mapping,
            pva_mapping,
        ) = _load_lookup_tables(cursor)

        # Produkt, Bereich und Abogruppe laden
        product_subscriptions = _load_product_subscriptions(cursor)

        # Perioden auf Kalendertage aufteilen
        daily_data = _create_daily_data(
            umsatz_data,
            start_date,
            end_date,
        )
        if daily_data.empty:
            logger.info("Keine Daten im Zielzeitraum gefunden.")
            return pd.DataFrame()

        # IVW-, Voucher- und PVA-Daten ergänzen
        result = _apply_joins(
            daily_data,
            ivw_subscriptions,
            vouchers,
            ivw_mapping,
            pva_mapping,
        )

        # Produkt, Bereich und Abogruppe ergänzen
        result = _apply_product_joins(
            result,
            product_subscriptions,
        )

        # Je Subscription und Tag aggregieren
        return _aggregate_subscription_daily(result)

    except Exception as e:
        logger.error(
            "Fehler bei der täglichen Subscription-Aggregation: %s",
            e,
            exc_info=True,
        )
        return pd.DataFrame()

    finally:
        if connection:
            connection.close()
